package com.gameaggregator.featureflagservice.infrastructure;import com.gameaggregator.featureflagservice.domain.FeatureFlag;import org.slf4j.*;import org.springframework.data.redis.core.StringRedisTemplate;import org.springframework.stereotype.Component;@Component public class FeatureFlagCache{static final Logger log=LoggerFactory.getLogger(FeatureFlagCache.class);final StringRedisTemplate redis;public FeatureFlagCache(StringRedisTemplate r){redis=r;}public void put(FeatureFlag f){try{redis.opsForValue().set("feature-flag:"+f.flagKey,"{\"enabled\":"+f.enabled+",\"killSwitch\":"+f.killSwitch+",\"rolloutPercentage\":"+f.rolloutPercentage+"}");}catch(RuntimeException e){log.warn("Feature flag cache unavailable",e);}}}